import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());
        String s = reader.readLine().trim();

        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                if (i < n) {
                    divisors.add(i);
                }
                int other = n / i;
                if (other != i && other < n) {
                    divisors.add(other);
                }
            }
        }
        Collections.sort(divisors);

        int[] baseCount = new int[26];
        int[] currentCount = new int[26];

        for (int len : divisors) {
            for (int i = 0; i < 26; i++) {
                baseCount[i] = 0;
            }
            for (int i = 0; i < len; i++) {
                baseCount[s.charAt(i) - 'a']++;
            }

            boolean ok = true;
            for (int block = 1; block < n / len; block++) {
                for (int i = 0; i < 26; i++) {
                    currentCount[i] = 0;
                }
                int start = block * len;
                for (int i = 0; i < len; i++) {
                    currentCount[s.charAt(start + i) - 'a']++;
                }

                for (int i = 0; i < 26; i++) {
                    if (baseCount[i] != currentCount[i]) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break;
            }

            if (ok) {
                System.out.println(s.substring(0, len));
                return;
            }
        }

        System.out.println("*");
    }
}
